def _sql(connection, query, parameters=()):
    return connection.exec_driver_sql(query, parameters) if hasattr(connection, "exec_driver_sql") else connection.execute(query, parameters)


def _one_scalar(connection, query, parameters=()):
    result = _sql(connection, query, parameters)
    if hasattr(result, "scalar_one"):
        return result.scalar_one()
    rows = result.fetchmany(2)
    if len(rows) != 1 or len(rows[0]) != 1:
        raise HeaderBoundsError("header_scalar_unavailable")
    return rows[0][0]

def _metadata_upper(rows, widths):
    """JSON byte bound for closed rows; text widths include quotes/escaping."""
    if type(rows) is not int or rows < 0 or any(type(size) is not int or size < 0 for size in widths):
        raise HeaderBoundsError("header_metadata_bound")
    row = 2 + sum(widths) + max(0, len(widths) - 1)
    return 2 + rows * row + max(0, rows - 1)


def _metadata_transaction_required(connection):
    import sqlite3
    from aiosqlite import Connection as AsyncSQLiteConnection
    from sqlalchemy.engine import Connection as SQLAlchemyConnection
    # The original retention owner passes its exact sqlite3 handle; live
    # session owners pass the exact SQLAlchemy connection and SQLite driver.
    # Neither attribute-shaped proxies nor a logical-only BEGIN qualify.
    try:
        if type(connection) is sqlite3.Connection:
            active = connection.in_transaction is True
        elif type(connection) is SQLAlchemyConnection:
            active = (not connection.closed and not connection.invalidated
                and connection.in_transaction() is True)
            if active:
                driver = connection.connection.driver_connection
                active = (type(driver) in (sqlite3.Connection, AsyncSQLiteConnection)
                    and driver.in_transaction is True)
        else:
            active = False
    except (sqlite3.ProgrammingError, ValueError):
        active = False  # Closed SQLite handles expose no active transaction.
    if not active:
        raise HeaderBoundsError("header_metadata_transaction_required")


def _metadata_memory_capacity(connection, budget, active):
    """Validate the original numerical payer; this grants no metadata access."""
    import asyncio
    from sqlalchemy.engine import Connection as SQLAlchemyConnection
    from sqlalchemy.ext.asyncio import AsyncSession
    from src.memory.header_bounds import _NativeMemoryNumericLedger
    from src.runtime_plugins.memory_producer import (
        _NativeMemoryDispatchSource, _MEMORY_SOURCE_SEAL,
        _validate_memory_completion_capacity_source,
        _validate_memory_completion_publication_capacity_source)
    from src.workspace.accounting_witness import (
        CompositionSessionGuard, _COMPOSITION_METADATA_GUARDS, _NativeMemoryRetention)
    from src.workflows.job_runtime import NativeServiceClaim
    if type(active) is not tuple or len(active) != 2:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    ledger, phase = active
    if (type(ledger) is not _NativeMemoryNumericLedger
            or phase not in {"effect", "capture", "completion"}
            or budget is not ledger.budget):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    ledger._checked()
    source = ledger.source
    retention = getattr(source, "_retention", None)
    if (type(source) is not _NativeMemoryDispatchSource
            or source._seal is not _MEMORY_SOURCE_SEAL or source._issued_id != id(source)
            or type(source.claim) is not NativeServiceClaim
            or type(retention) is not _NativeMemoryRetention
            or retention.source is not source or retention.ledger is not ledger
            or retention.operation is not ledger.operation or retention.prepared is not ledger.prepared):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    retention._checked()
    binding = ledger.bindings.get(phase)
    if (type(binding) is not tuple or len(binding) != 6
            or type(binding[0]) is not AsyncSession
            or binding[5] is not asyncio.current_task()
            or binding[0].sync_session.get_transaction() is not binding[1]
            or type(connection) is not SQLAlchemyConnection
            or connection.connection.driver_connection is not binding[2]
            or not binding[2].in_transaction
            or (phase != "completion" and (binding[0] is not ledger.operation.db
                or binding[1] is not ledger.operation.transaction
                or binding[2] is not ledger.operation.driver))):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    # Lookup only an already enrolled connection; do not acquire a connection
    # or manufacture a certificate while checking resource ownership.
    enrolled = binding[1]._connections.get(connection)
    guard = binding[0].info.get("composition_guard")
    if (type(enrolled) is not tuple or len(enrolled) != 4 or enrolled[0] is not connection
            or connection.get_transaction() is not enrolled[1]
            or type(guard) is not CompositionSessionGuard
            or guard not in _COMPOSITION_METADATA_GUARDS or guard._retention_closed
            or guard.db is not binding[0] or guard.header_budget is not budget
            or getattr(guard, "_native_memory_source_retention", None) is not retention):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    if phase == "completion":
        if retention.completed is True:
            _validate_memory_completion_publication_capacity_source(
                source, source.claim, guard=guard)
        else:
            _validate_memory_completion_capacity_source(source, source.claim)


def _metadata_precharge(connection, budget, upper, appearance):
    from src.memory.header_bounds import _SESSION_NUMERIC_READS, _MEMORY_LEDGER_PHASE
    active = _MEMORY_LEDGER_PHASE.get()
    if budget is None:
        if active is not None:
            raise HeaderBoundsError("header_metadata_owner_unavailable")
        return
    if (type(budget) is not HeaderReadBudget or type(upper) is not int or upper < 0
            or _SESSION_NUMERIC_READS.get() is not None):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    _metadata_transaction_required(connection)
    if active is not None:
        _metadata_memory_capacity(connection, budget, active)
    current = _CURRENT.get()
    if current is not None and (current.connection is not connection or current.budget is not budget):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    budget.debit(upper, appearance=("metadata-prequery", *appearance))


def _metadata_size(value):
    # No JSON/output object is built while validating the delivered bound.
    if value is None: return 4
    if type(value) is bool: return 4 if value else 5
    if type(value) is int:
        if not -(2**63) <= value < 2**63: raise HeaderBoundsError("header_metadata_bound")
        return 20
    if type(value) is float: return 64
    if type(value) is str:
        return 2 + sum(2 if char in '\"\\' else (6 if ord(char) < 32 or 127 <= ord(char) <= 65535
            else (12 if ord(char) > 65535 else 1)) for char in value)
    return 2 + sum(_metadata_size(item) for item in value) + max(0, len(value) - 1)


def _metadata_rows(connection, query, parameters, *, _header_budget, upper, appearance, bounded_query=None):
    source_frame = _compiler_bounds._native_memory_header_logical_frame(connection, _header_budget)
    if source_frame is not None:
        source_query = bounded_query if _header_budget is not None and bounded_query is not None else query
        source_frame.debit(2 * _native_memory_metadata_logical_width(source_query)
            + 2 * _native_memory_metadata_logical_width(parameters) + 2 * upper,
            appearance=("native-memory-header-logical", "metadata-input-result"))
    if _header_budget is None:
        return list(_sql(connection, query, parameters))
    # Delivery, original list-of-row copy and JSON metadata copy are distinct.
    for stage in ("delivery", "row-copy", "encoded-copy"):
        _metadata_precharge(connection, _header_budget, upper, (*appearance, stage))
    rows = list(_sql(connection, bounded_query or query, parameters))
    if _metadata_size(rows) > upper:
        raise HeaderBoundsError("header_metadata_bound")
    return rows


def _native_memory_metadata_logical_width(value):
    """Scalar encoded input width; no SQL, JSON, UTF8 or container copy."""
    if value is None:
        return 4
    if type(value) is bool:
        return 5
    if type(value) is int:
        if not -(2**63) <= value < 2**63:
            raise HeaderBoundsError("header_metadata_bound")
        return 20
    if type(value) is str:
        return 2 + 6 * _compiler_bounds._native_memory_utf8_width(value)
    if type(value) is tuple:
        width = 2 + max(0, len(value) - 1)
        for item in value:
            width += _native_memory_metadata_logical_width(item)
        return width
    raise HeaderBoundsError("memory_header_logical_input_unavailable")


def _native_memory_discover_logical_upper(descriptor, key, tombstone, remaining):
    """Original locator construction, bounded by its unchanged LIMIT."""
    known = False
    for item in _compiler_bounds._DESCRIPTORS:
        if descriptor is item:
            known = True
            break
    if not known or type(tombstone) is not bool:
        raise HeaderBoundsError("header_descriptor_unavailable")
    limit = MAX_ROWS if remaining is None else remaining
    if type(limit) is not int or not 0 <= limit <= MAX_ROWS:
        raise HeaderBoundsError("header_request_bound")
    if key is not None:
        if type(key) is not str or not key or _compiler_bounds._native_memory_utf8_width(key) > 512:
            raise HeaderBoundsError("header_request_bound")
        key_width = _native_memory_metadata_logical_width(key)
    else:
        key_width = 4
    count = 2 if key is not None or tombstone else limit + 1
    # The original query template contains seven column substitutions and
    # one table substitution. The optional suffix adds one key or <=128-char
    # closed model index identifier. No selector or row body is evaluated.
    suffix = 0
    if tombstone:
        suffix = len(' INDEXED BY "" WHERE memory_id=?') + 128
    elif key is not None:
        suffix = len(' WHERE ""=?') + len(descriptor.key)
    query = 212 + 7 * len(descriptor.key) + len(descriptor.table) + suffix
    row_width = 2 + 4 + 20 + 44 + 20 + 3074 + 20
    rows_width = 2 + count * row_width + max(0, count - 1)
    id_width = 20 if descriptor.table == "work_board_events" else 3074
    ids = 2 + count * id_width + max(0, count - 1)
    # Format/concatenation frontiers, suffix and parameter tuple; original
    # ids list, uniqueness set, returned tuple and physical enrollment tuples.
    upper = 3 * (6 * query + 2) + 6 * suffix + 2 + 3 + key_width + 20
    upper += 3 * ids + count * (3 + 6 * len(descriptor.table) + 2 + 20)
    # The default path's list-of-row metadata copy, canonical JSON and UTF8
    # copies are prepaid from the same original five-field locator bound.
    upper += 3 * rows_width + (2 + 3 + 6 * len(descriptor.table) + 2 + key_width + 5 + ids)
    upper += 4 * 41 + count * 41
    return upper


