def _descriptor_integer_size(value):
    if type(value) is not int or not -(2**63) <= value < 2**63:
        raise HeaderBoundsError("header_metadata_bound")
    negative = value < 0
    magnitude = -value if negative else value
    digits = 1
    while magnitude >= 10:
        magnitude //= 10
        digits += 1
    return digits + int(negative)


def _descriptor_xinfo_size(rows):
    # Size traversal only; domain denials stay at original schema-check points.
    size = 2 + max(0, len(rows) - 1)
    for row in rows:
        size += 2 + max(0, len(row) - 1)
        for cell in row:
            if type(cell) is int:
                size += _descriptor_integer_size(cell)
            else:
                size += _metadata_size(cell)
    return size


