def _compiler_class_field(cls, name):
    # Bypass metaclass/property hooks; never inspect a cold instance property.
    for base in type.__getattribute__(cls, "__mro__"):
        fields = type.__getattribute__(base, "__dict__")
        if name in fields:
            return fields[name]
    return _COMPILER_MISSING


