def _check_original_compiler_bindings():
    if (dialect is not _COMPILER_FACTORY or _compiler_types.adapt_type is not _ORIGINAL_ADAPT_TYPE
            or _compiler_type_api.adapt_type is not _ORIGINAL_ADAPT_TYPE
            or _compiler_bounds.sqlite_dialect is not _COMPILER_FACTORY
            or _compiler_bounds._descriptor is not _ORIGINAL_DESCRIPTOR_FACTORY):
        raise HeaderBoundsError("header_schema_changed")
    for cls, name, original in _ORIGINAL_COMPILER_BINDINGS:
        if _compiler_class_field(cls, name) is not original:
            raise HeaderBoundsError("header_schema_changed")
    if len(_COMPILER_COLSPECS) != len(_ORIGINAL_COMPILER_COLSPECS):
        raise HeaderBoundsError("header_schema_changed")
    for key, value in _ORIGINAL_COMPILER_COLSPECS:
        if _COMPILER_COLSPECS.get(key) is not value:
            raise HeaderBoundsError("header_schema_changed")


def _compiler_direct_fields(value):
    if type(value) not in _COMPILER_CLASSES:
        raise HeaderBoundsError("header_schema_changed")
    fields = object.__getattribute__(value, "__dict__")
    for name in _COMPILER_METHOD_NAMES:
        if name in fields and name not in {"length", "collation", "impl", "impl_instance", "enums", "enum_class", "timezone", "precision", "asdecimal"}:
            raise HeaderBoundsError("header_schema_changed")
    if _compiler_class_field(type(value), "_variant_mapping"):
        raise HeaderBoundsError("header_schema_changed")
    return fields


def _compiler_varchar_cost(fields, spelling):
    length = fields.get("length", _COMPILER_MISSING)
    if fields.get("collation", _COMPILER_MISSING) is not None:
        raise HeaderBoundsError("header_schema_changed")
    if length is None or type(length) is int and length == 0:
        if spelling != "VARCHAR":
            raise HeaderBoundsError("header_schema_changed")
        return 18
    if type(length) is not int or length < 1 or type(spelling) is not str or not 10 <= len(spelling) <= 128:
        raise HeaderBoundsError("header_schema_changed")
    for index, char in enumerate("VARCHAR("):
        if spelling[index] != char:
            raise HeaderBoundsError("header_schema_changed")
    if spelling[-1] != ")" or spelling[8] == "0":
        raise HeaderBoundsError("header_schema_changed")
    parsed = 0
    for index in range(8, len(spelling) - 1):
        digit = ord(spelling[index]) - 48
        if not 0 <= digit <= 9:
            raise HeaderBoundsError("header_schema_changed")
        parsed = parsed * 10 + digit
    if length != parsed:
        raise HeaderBoundsError("header_schema_changed")
    digits = len(spelling) - 9
    return (digits + 2) + (digits + 4) + 2 * (digits + 11)


def _compiler_type_cost(value, spelling, table, name):
    if type(spelling) is not str:
        raise HeaderBoundsError("header_schema_changed")
    fields = _compiler_direct_fields(value)
    cls = type(value)
    if cls is _CompilerAutoString:
        if "length" in fields or "collation" in fields:
            raise HeaderBoundsError("header_schema_changed")
        impl = fields.get("impl")
        if type(impl) is not _compiler_types.String or fields.get("impl_instance", impl) is not impl:
            raise HeaderBoundsError("header_schema_changed")
        return _compiler_varchar_cost(_compiler_direct_fields(impl), spelling)
    if cls is _compiler_types.Enum:
        roster = _COMPILER_ENUM_ROSTER.get((table, name))
        if roster is None or fields.get("enum_class") is not roster[0]:
            raise HeaderBoundsError("header_schema_changed")
        labels = fields.get("enums")
        members = type.__getattribute__(roster[0], "__dict__").get("_member_map_")
        names = type.__getattribute__(roster[0], "__dict__").get("_member_names_")
        if (type(labels) is not list or type(names) is not list or type(members) is not dict
                or len(labels) != len(roster[1]) or len(names) != len(labels) or len(members) != len(labels)):
            raise HeaderBoundsError("header_schema_changed")
        longest = 0
        for index, expected in enumerate(roster[1]):
            if type(labels[index]) is not str or type(names[index]) is not str or labels[index] != expected or names[index] != expected:
                raise HeaderBoundsError("header_schema_changed")
            member = members.get(expected)
            stored = object.__getattribute__(member, "__dict__") if type(member) is roster[0] else None
            if stored is None or type(stored.get("_name_")) is not str or stored["_name_"] != expected or type(stored.get("_value_")) is not str or stored["_value_"] != expected:
                raise HeaderBoundsError("header_schema_changed")
            longest = max(longest, len(expected))
        enum_name = fields.get("name")
        if (fields.get("values_callable") is not None or fields.get("_omit_aliases") is not True
                or fields.get("_sort_key_function") is not _ORIGINAL_ENUM_SORT_DEFAULT
                or fields.get("native_enum") is not True or fields.get("create_constraint") is not False
                or fields.get("validate_strings") is not False or type(fields.get("length")) is not int
                or fields["length"] != longest or type(fields.get("_default_length")) is not int
                or fields["_default_length"] != longest
                or fields.get("schema") is not None or fields.get("metadata") is not None
                or fields.get("inherit_schema") is not False or fields.get("_create_events") is not True
                or type(enum_name) is not _CompilerQuotedName or enum_name != roster[2]
                or object.__getattribute__(enum_name, "quote") is not None):
            raise HeaderBoundsError("header_schema_changed")
        return _compiler_varchar_cost(fields, spelling)
    if cls is _compiler_types.Integer and spelling == "INTEGER":
        return 18
    if cls is _compiler_types.DateTime and spelling == "DATETIME" and fields.get("timezone") is False:
        return 20
    if cls is _compiler_types.Boolean and spelling == "BOOLEAN" and fields.get("create_constraint") is False:
        return 18
    if cls is _compiler_types.Float and spelling == "FLOAT" and fields.get("precision") is None and fields.get("asdecimal") is False:
        return 14
    raise HeaderBoundsError("header_schema_changed")


def _prepay_descriptor_compiler(connection, model, columns, spellings, budget, *, table):
    if budget is None:
        return
    _check_original_compiler_bindings()
    upper = 0
    for index, name in enumerate(columns):
        mapped = type.__getattribute__(model, "__dict__")["__table__"].columns[name]
        if type(mapped) is not _CompilerColumn:
            raise HeaderBoundsError("header_schema_changed")
        current_type = object.__getattribute__(mapped, "__dict__").get("type")
        upper += _compiler_type_cost(current_type, spellings[index], table, name)
    _metadata_precharge(connection, budget, upper, ("descriptor-compiler", table))


def _native_memory_descriptor_logical_upper(descriptor, *, _bounded=False):
    """Original fixed schema inputs and bounded result-copy constructions."""
    known = False
    for item in _compiler_bounds._DESCRIPTORS:
        if descriptor is item:
            known = True
            break
    if not known:
        raise HeaderBoundsError("header_descriptor_unavailable")
    n = len(descriptor.columns)
    if type(_bounded) is not bool:
        raise HeaderBoundsError("header_metadata_bound")
    if _bounded:
        widths = _DESCRIPTOR_XINFO_WIDTHS.get(descriptor.table)
        if widths is None or widths[0] != n or n > 99:
            raise HeaderBoundsError("header_descriptor_unavailable")
        rows = (n + 1) * (widths[1] + widths[2] + 16) + 1
        names = 2 + n + (n + 1) * (widths[1] + 2)
        expected_names = 2 + max(0, n - 1)
        for name in descriptor.columns:
            expected_names += len(name) + 2
        # Actual bounded path: FIVE parameters and FIVE scalar widths before
        # the original wrapper, two name sets, sorted schema list and both
        # primary-key tuples. It returns0; no None-path JSON/UTF copy exists.
        upper = 2 + 4 + 4 * 20 + 6 * len(descriptor.table) + 2
        upper += 2 + 4 + 5 * 20
        upper += names + 2 * expected_names + rows + 2 * names
        # Original metadata upper, schema predicates/PK controls and the
        # TWO per-row string sizing generators of _descriptor_xinfo_size.
        upper += (10 + 2 * (n + 1)) * 41
        # The original table-list caller tuple and metadata-upper input.
        upper += 2 + 6 * len(descriptor.table) + 2 + 2 + 20 + 41
        return upper
    # The unchanged pragma clips both strings to128 bytes before delivery.
    row = 2 + 4 + 770 + 770 + 3 * 20
    rows = 2 + (n + 1) * row + n
    # List-of-row copy, canonical JSON and UTF8, including the original
    # final schema-cost return. The SQL literal is169 ASCII characters.
    upper = 3 * rows + 2 * (6 * 169 + 2)
    upper += 2 * (2 + 1 + 6 * len(descriptor.table) + 2 + 20)
    # The existing metered xinfo branch passes FIVE original parameters;
    # include its caller tuple before _descriptor_xinfo_rows receives it.
    upper += 2 + 4 + 4 * 20 + 6 * len(descriptor.table) + 2
    names = 2 + max(0, n - 1)
    for name in descriptor.columns:
        names += 6 * len(name) + 2
    # Original name sets, sorted schema list, primary-key output and model
    # primary-key generator; unsupported schema still fits the clipped rows.
    upper += 2 * rows + 5 * names + 8 * 41 + n * 41
    upper += 2 * (6 * 71 + 2) + 2 * (2 + 6 * len(descriptor.table) + 2)
    # Original per-column compiled spelling and its .upper() result. The
    # compiler's existing private typed grammar is paid separately below.
    for spelling in descriptor.sql_types:
        upper += 2 * (6 * len(spelling) + 2)
    return upper


def validate_descriptor_schema(connection, descriptor, *, _header_budget=None):
    source_frame = _compiler_bounds._native_memory_header_logical_frame(connection, _header_budget)
    if source_frame is not None:
        source_frame.debit(_native_memory_descriptor_logical_upper(descriptor,
            _bounded=_header_budget is source_frame),
            appearance=("native-memory-header-logical", "schema-construction"))
    model = _COMPOSITION_MODELS.get(descriptor.table)
    if model is None:
        # Original byte-only legacy descriptors use the same actual mapped table.
        from src.db import models
        model = next((c for c in vars(models).values() if isinstance(c, type)
                      and getattr(c, "__tablename__", None) == descriptor.table), None)
    if model is None:
        raise HeaderBoundsError("header_descriptor_unavailable")
    if source_frame is not None and _header_budget is None:
        _prepay_descriptor_compiler(connection, model, descriptor.columns, descriptor.sql_types,
            source_frame, table=descriptor.table)
    if _header_budget is not None:
        _prepay_descriptor_compiler(connection, model, descriptor.columns, descriptor.sql_types,
            _header_budget, table=descriptor.table)
    if _header_budget is None:
        schema = _metadata_rows(connection, 'SELECT CASE WHEN octet_length(name)<=128 THEN name END,'
            'CASE WHEN octet_length(type)<=128 THEN type END,"notnull",pk,hidden '
            'FROM pragma_table_xinfo(?) LIMIT ?', (descriptor.table, len(descriptor.columns)+1), _header_budget=None, upper=_metadata_upper((len(descriptor.columns)+1), (770,770,20,20,20)), appearance=('descriptor-xinfo',))
    else:
        widths = _DESCRIPTOR_XINFO_WIDTHS.get(descriptor.table)
        n = len(descriptor.columns)
        if widths is None or widths[0] != n:
            raise HeaderBoundsError("header_descriptor_unavailable")
        schema = _descriptor_xinfo_rows(connection, (widths[1], widths[2], n, descriptor.table, n+1),
            budget=_header_budget, upper=_metadata_upper(n+1, (widths[1]+2, widths[2]+2, 2, 2, 1)))
        if any(len(row) != 5 for row in schema):
            raise HeaderBoundsError("header_schema_changed")
    expected = model.__table__
    if (_header_budget is not None and any(type(r[0]) is not str or type(r[4]) is not int for r in schema)):
        raise HeaderBoundsError("header_schema_changed")
    if (len(schema) != len(descriptor.columns) or {r[0] for r in schema} != set(descriptor.columns)
            or any(r[4] != 0 or r[0] in {"rowid", "_rowid_", "oid"} for r in schema)):
        raise HeaderBoundsError("header_schema_changed")
    if _header_budget is not None and any(type(r[3]) is not int or not 0 <= r[3] <= n for r in schema):
        raise HeaderBoundsError("header_schema_changed")
    pk = tuple(r[0] for r in sorted(schema, key=lambda r:r[3]) if r[3])
    if pk != tuple(c.name for c in expected.primary_key.columns):
        raise HeaderBoundsError("header_schema_changed")
    for name, sql_type, notnull, _pk, _hidden in schema:
        column = expected.columns[name]
        if _header_budget is not None:
            _check_original_compiler_bindings()
            index = descriptor.columns.index(name)
            _compiler_type_cost(column.type, descriptor.sql_types[index], descriptor.table, name)
        if (sql_type != column.type.compile(dialect=dialect()).upper()
                or (_header_budget is not None and (type(notnull) is not int or notnull not in (0, 1)))
                or notnull != int(not column.nullable)):
            raise HeaderBoundsError("header_schema_changed")
    table = _descriptor_metadata_rows(connection, 'SELECT wr FROM pragma_table_list WHERE schema="main" AND name=? LIMIT 2', (descriptor.table,), _header_budget=_header_budget, upper=_metadata_upper(2, (20,)), appearance=('descriptor-table',))
    if (len(table) != 1 or (_header_budget is not None and (len(table[0]) != 1 or type(table[0][0]) is not int)) or table[0][0] != 0):
        raise HeaderBoundsError("header_schema_changed")
    if pk != (descriptor.key,):
        _validate_locator(connection, descriptor.table, descriptor.key, model, budget=_header_budget, _header_budget=_header_budget)
    return _metadata_cost([list(r) for r in schema]) if _header_budget is None else 0


def _native_memory_index_logical_upper(table, column, model):
    """The original fixed index grammar, before any filtered index list."""
    if _COMPOSITION_MODELS.get(table) is not model:
        raise HeaderBoundsError("header_descriptor_unavailable")
    count = len(model.__table__.indexes) + len(model.__table__.constraints) + 1
    names = 2
    for index in model.__table__.indexes:
        if type(index.name) is not str or not index.name.isascii() or len(index.name) > 128:
            raise HeaderBoundsError("header_locator_unsupported")
        names += 6 * len(index.name) + 3
    # Original source filter/list and each column-name tuple; the original
    # SQL clips metadata names at128 bytes and limits index parts to3.
    upper = names + 2 + 2 * 41
    for index in model.__table__.indexes:
        upper += 2 + 41
        for item in index.columns:
            upper += 6 * len(item.name) + 3
    index_rows = 2 + count * (2 + 3 + 770 + 20 + 14 + 20) + max(0, count - 1)
    part_rows = 2 + 3 * (2 + 4 + 770 + 770 + 3 * 20) + 2
    # Both unchanged SQL templates/parameter tuples, matches/keys/slices,
    # and original list-of-row/JSON/UTF8 copies on the default metadata path.
    upper += 2 * (6 * 155 + 2) + 2 * (6 * 150 + 2)
    upper += 2 * (3 + 6 * len(table) + 2 + 20) + 2 * (2 + 770)
    upper += 4 * index_rows + 4 * part_rows + 4 * 41 + 2 + 3 * 20
    upper += 2 + 4 * 20 + 6 * len(column) + 2
    return upper


def _validate_locator(connection, table, column, model=None, *, budget=None, _header_budget=None):
    source_frame = _compiler_bounds._native_memory_header_logical_frame(connection, budget)
    if source_frame is not None:
        if _header_budget is None:
            # The unchanged default query does not clip arbitrary SQLite
            # index names. A model index is not evidence of the live schema.
            raise HeaderBoundsError("memory_header_logical_index_dimensions_unavailable")
        source_model = model or _COMPOSITION_MODELS.get(table)
        source_frame.debit(_native_memory_index_logical_upper(table, column, source_model),
            appearance=("native-memory-header-logical", "index-construction"))
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    model = model or _COMPOSITION_MODELS[table]
    source = [i for i in model.__table__.indexes if i.unique and tuple(c.name for c in i.columns)==(column,)]
    if len(source) != 1:
        raise HeaderBoundsError("header_locator_unsupported")
    name = source[0].name
    index_width = (_original_locator_schema_width(connection, table, model, _header_budget)
        if _header_budget is not None else None)
    targeted_index = False
    if index_width is not None:
        # The original same-frame schema proof authenticates this mapped name.
        # Pay sizing arithmetic, membership/type predicates and parameter work
        # before sizing or constructing the new three-parameter tuple.
        _metadata_precharge(connection, _header_budget, 256,
            ("locator-indexes", "target-planning"))
        targeted_index = (type(name) is str and name in _NAMED_INDEXES
                and name.isascii() and len(name) <= 128)
    if targeted_index:
        index_limit = len(model.__table__.indexes)+len(model.__table__.constraints)+1
        target_width = max(4, len(name)+2)
        table_width = len(table)+2
        parameter_width = target_width+table_width+24
        _metadata_precharge(connection, _header_budget, 3*parameter_width,
            ("locator-indexes", "target-parameters"))
        # Exact closed ASCII SQL: 182 bytes, JSON quoted width186.
        # Three independent input copies remain separately paid.
        _metadata_precharge(connection, _header_budget, 558,
            ("locator-indexes", "target-sql-input"))
        parameters = (name, table, index_limit)
        rows = _metadata_rows(connection,
            'SELECT CASE WHEN name COLLATE BINARY=? AND octet_length(name)<=128 THEN name END,"unique",CASE WHEN origin IN (\'pk\',\'u\',\'c\') THEN origin END,partial FROM pragma_index_list(?) LIMIT ?',
            parameters, _header_budget=_header_budget,
            upper=_metadata_upper(index_limit, (target_width,20,4,20)),
            appearance=('locator-indexes',))
    else:
        rows = _metadata_rows(connection, 'SELECT name,"unique",origin,partial FROM pragma_index_list(?) LIMIT ?', (table, len(model.__table__.indexes)+len(model.__table__.constraints)+1), _header_budget=_header_budget, upper=_metadata_upper((len(model.__table__.indexes)+len(model.__table__.constraints)+1), (770 if index_width is None else index_width,20,14 if index_width is None else 4,20)), appearance=('locator-indexes',), bounded_query=('SELECT CASE WHEN octet_length(name)<=128 THEN name END,"unique",CASE WHEN octet_length(origin)<=2 THEN origin END,partial FROM pragma_index_list(?) LIMIT ?' if index_width is None else 'SELECT CASE WHEN octet_length(name)<=128 THEN name END,"unique",CASE WHEN origin IN (\'pk\',\'u\',\'c\') THEN origin END,partial FROM pragma_index_list(?) LIMIT ?'))
    if budget is not None:
        if _header_budget is None:
            budget.debit(_metadata_cost([list(r) for r in rows]), appearance=("operator-token-index-list",))
    match = [r for r in rows if r[0] == name]
    if len(match) != 1 or tuple(match[0][1:]) != (1,"c",0):
        raise HeaderBoundsError("header_locator_changed")
    column_width = (_original_locator_schema_width(connection, table, model, _header_budget, column_names=True)
        if _header_budget is not None else None)
    # Only this issuer's already-paid mapped schema proof narrows collation.
    # Key rows accept BINARY only; nonkey collation is not an authority input.
    # NULL preserves rejection for a non-BINARY key without bounding its raw
    # collation name. Ordinary/default and other metered callers stay unchanged.
    parts = _metadata_rows(connection, 'SELECT name,coll,desc,key,cid FROM pragma_index_xinfo(?) LIMIT 3', (name,), _header_budget=_header_budget, upper=_metadata_upper(3, (770 if column_width is None else column_width,770 if column_width is None else 8,20,20,20)), appearance=('locator-parts',), bounded_query=('SELECT CASE WHEN octet_length(name)<=128 THEN name END,CASE WHEN octet_length(coll)<=128 THEN coll END,desc,key,cid FROM pragma_index_xinfo(?) LIMIT 3' if column_width is None else 'SELECT CASE WHEN octet_length(name)<=128 THEN name END,CASE WHEN coll=\'BINARY\' THEN coll END,desc,key,cid FROM pragma_index_xinfo(?) LIMIT 3'))
    if budget is not None:
        if _header_budget is None:
            budget.debit(_metadata_cost([list(r) for r in parts]), appearance=("operator-token-index-parts",))
    keys = [r for r in parts if r[3]==1]
    if len(parts)!=2 or len(keys)!=1 or tuple(keys[0][:4])!=(column,"BINARY",0,1):
        raise HeaderBoundsError("header_locator_changed")
    return name


def _headers(connection, descriptor, identities, *, _header_budget=None):
    fields=['_rowid_']
    for index, name in enumerate(descriptor.columns):
        if _header_budget is None:
            storage = f'typeof("{name}")'
            number = f"CASE WHEN typeof(\"{name}\") IN ('integer','real') THEN \"{name}\" END"
        else:
            storage = (f'CASE typeof("{name}") '
                "WHEN 'null' THEN 'null' WHEN 'text' THEN 'text' "
                "WHEN 'integer' THEN 'integer' WHEN 'real' THEN 'real' "
                "WHEN 'blob' THEN 'blob' ELSE NULL END")
            kind = descriptor.kinds[index]
            number = ("NULL" if kind == "text" else
                f"CASE WHEN typeof(\"{name}\")='{kind}' THEN \"{name}\" END")
        fields += [storage, f'octet_length("{name}")', number]
    row_bound = 1 if (_header_budget is not None and
        _original_common_header_single_row(connection, descriptor, identities, _header_budget)) else 2
    source_name_factor = 6
    if row_bound == 1 and descriptor.table.isascii() and descriptor.table.isidentifier():
        source_names_closed = True
        for name in descriptor.columns:
            if not name.isascii() or not name.isidentifier():
                source_names_closed = False
                break
        if source_names_closed:
            source_name_factor = 1
    result={}
    for key in identities:
        if _header_budget is not None:
            if type(key) not in {str, int}:
                raise HeaderBoundsError("header_request_bound")
            if type(key) is str:
                key_octets = sum(1 if ord(char)<128 else 2 if ord(char)<2048
                    else 3 if ord(char)<=65535 else 4 for char in key)
                if key_octets > 512:
                    raise HeaderBoundsError("header_request_bound")
                key_copy_upper = 6*key_octets + 2
            else:
                # Original SQLite integer locators fit signed int64 JSON.
                key_copy_upper = 20
        rows=_metadata_rows(connection, 'SELECT '+','.join(fields)+f' FROM "{descriptor.table}" WHERE "{descriptor.key}"=? LIMIT 2', (key,), _header_budget=_header_budget, upper=_metadata_upper(row_bound, (20, *(
            [width for kind in descriptor.kinds for width in
                (9, 20, 4 if kind == "text" else 20 if kind == "integer" else 64)]
            if _header_budget is not None else [44,20,64] * len(descriptor.columns)))), appearance=('row-header',))
        if len(rows)!=1: raise HeaderBoundsError("header_row_unavailable")
        row=rows[0]
        if _header_budget is not None:
            copy_upper = key_copy_upper + source_name_factor*len(descriptor.table) + sum(source_name_factor*len(name)+12 for name in descriptor.columns) + 256
            _metadata_precharge(connection, _header_budget, copy_upper, ("row-header", "skeleton-copy"))
            fact_upper = key_copy_upper + source_name_factor*len(descriptor.table) + 256
            _metadata_precharge(connection, _header_budget, fact_upper, ("row-header", "header-fact-copy"))
        skeleton=["native-composition-memory.v1",descriptor.table,key,[[n,None] for n in descriptor.columns]]
        cost=len(json.dumps(skeleton,ensure_ascii=True,separators=(",",":")).encode())+128
        for i,(kind,nullable) in enumerate(zip(descriptor.kinds,descriptor.nullable)):
            storage,size,number=row[1+i*3:4+i*3]
            if storage=="null":
                if not nullable:raise HeaderBoundsError("header_scalar_unavailable")
                continue
            if storage!=kind:raise HeaderBoundsError("header_scalar_type_unsupported")
            if kind=="text":cost+=6*size+2-4
            elif kind=="integer":
                if type(number) is not int or not -(2**63)<=number<2**63:raise HeaderBoundsError("header_scalar_unavailable")
                cost+=20-4
            else:
                if type(number) is not float or not math.isfinite(number):raise HeaderBoundsError("header_scalar_unavailable")
                cost+=64-4
        result[(descriptor.table,key)]=(row[0],cost)
    return result


def _prepay_selected_whole_locator_inputs(connection, descriptor, budget, *, remaining):
    # Zero-debit original owner check before source sizing or allocation.
    _selected_census_owner(connection, budget)
    from src.memory.header_bounds import _COMPOSITION_KEYS
    if type(remaining) is not int or not 0 <= remaining <= MAX_ROWS:
        raise HeaderBoundsError("header_metadata_bound")
    table, column = descriptor.table, descriptor.key
    if (type(table) is not str or type(column) is not str
            or COMPOSITION_DESCRIPTORS.get(table) is not descriptor
            or _COMPOSITION_KEYS.get(table) != column
            or not table.isascii() or not column.isascii()
            or not 0 < len(table) <= 128 or not 0 < len(column) <= 128):
        raise HeaderBoundsError("header_descriptor_unavailable")
    # Literal-source AST: Qa=243+5K+T,F=13; Qd=212+7K+T,F=18.
    # Selected whole delivery uses one JoinedStr; other locator paths retain their frontiers.
    numeric = 3 * (243 + 5 * len(column) + len(table) + 2) + 3 * 13 + 2 + 3 * 22
    delivery = 3 * (212 + 7 * len(column) + len(table) + 2) + 3 * 18 + 2 + 3 * 22
    _metadata_precharge(connection, budget, numeric, ("row-locator-input", "numeric-construction"))
    _metadata_precharge(connection, budget, delivery, ("row-locator-input", "delivery-construction"))
    # Two original total_changes/main/temp query sets; fixed SQL+empty binds.
    _metadata_precharge(connection, budget, 516, ("row-locator-input", "state-cookie-input"))


def _selected_whole_locator_bound(connection, descriptor, budget, *, remaining):
    """Paid numeric envelope for the original ordered locator prefix only."""
    if type(budget) is not HeaderReadBudget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    if type(remaining) is not int or not 0 <= remaining <= MAX_ROWS:
        raise HeaderBoundsError("header_metadata_bound")
    # This new private numeric tuple is a separate appearance from SQL rows.
    _metadata_precharge(connection, budget, 43, ("row-locator-numeric", "facts-copy"))
    column = descriptor.key
    rows = _metadata_rows(connection,
        f'SELECT COUNT(*),COALESCE(SUM(90 + CASE WHEN typeof("{column}")=\'text\' '
        f'AND octet_length("{column}") BETWEEN 1 AND 512 '
        f'THEN 6*octet_length("{column}")+2 ELSE 4 END '
        f'+ CASE WHEN typeof("{column}")=\'integer\' THEN 20 ELSE 4 END),0) '
        f'FROM (SELECT "{column}" FROM "{descriptor.table}" ORDER BY _rowid_ LIMIT ?)',
        (remaining + 1,), _header_budget=budget,
        upper=_metadata_upper(2, (20, 20)), appearance=("row-locator-numeric",))
    if len(rows) != 1 or len(rows[0]) != 2:
        raise HeaderBoundsError("header_metadata_bound")
    count, summed_width = rows[0]
    if (type(count) is not int or type(summed_width) is not int
            or not 0 <= count <= remaining + 1 or not 98 * count <= summed_width <= count * 3184
            or count == 0 and summed_width != 0):
        raise HeaderBoundsError("header_metadata_bound")
    if count > remaining:
        raise HeaderBoundsError("header_reference_bound")
    return count, 2 + summed_width + max(0, count - 1)


def _discover(connection, descriptor, budget, key=None, tombstone=False, remaining=None, *, database_identity=None, _header_budget=None):
    source_frame = _compiler_bounds._native_memory_header_logical_frame(connection, budget)
    if source_frame is not None:
        source_frame.debit(_native_memory_discover_logical_upper(descriptor, key, tombstone, remaining),
            appearance=("native-memory-header-logical", "locator-construction"))
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    schema_cost = validate_descriptor_schema(connection, descriptor, _header_budget=_header_budget)
    if _header_budget is None:
        budget.debit(schema_cost, appearance=("descriptor-schema", descriptor.table))
    selected_whole = _header_budget is not None and key is None and not tombstone
    if selected_whole:
        _prepay_selected_whole_locator_inputs(connection, descriptor, budget,
            remaining=MAX_ROWS if remaining is None else remaining)
    if tombstone:
        name=_validate_locator(connection,descriptor.table,"memory_id",budget=_header_budget,_header_budget=_header_budget)
        suffix=f' INDEXED BY "{name}" WHERE memory_id=?'
        parameters=(key,2)
    elif key is not None:
        suffix=f' WHERE "{descriptor.key}"=?'
        parameters=(key,2)
    else:
        suffix=''; parameters=((MAX_ROWS if remaining is None else remaining)+1,)
    if selected_whole:
        locator_state = _state(connection, _header_budget=_header_budget)
        locator_cookies = _snapshot_schema_cookies(connection, budget, _header_budget=_header_budget)
        locator_count, locator_upper = _selected_whole_locator_bound(connection, descriptor, budget,
            remaining=MAX_ROWS if remaining is None else remaining)
    else:
        locator_upper = _metadata_upper((2 if key is not None or tombstone else
            (MAX_ROWS if remaining is None else remaining)+1), (20,44,20,3074,20))
    column=descriptor.key
    if selected_whole:
        locator_query = (f'SELECT _rowid_,typeof("{column}"),octet_length("{column}"),'
        f"CASE WHEN typeof(\"{column}\")='text' THEN CASE WHEN octet_length(\"{column}\") BETWEEN 1 AND 512 THEN \"{column}\" END END,"
        f"CASE WHEN typeof(\"{column}\")='integer' THEN \"{column}\" END FROM \"{descriptor.table}\""
        f' ORDER BY _rowid_ LIMIT ?')
    else:
        locator_query = (f'SELECT _rowid_,typeof("{column}"),octet_length("{column}"),'
        f"CASE WHEN typeof(\"{column}\")='text' THEN CASE WHEN octet_length(\"{column}\") BETWEEN 1 AND 512 THEN \"{column}\" END END,"
        f"CASE WHEN typeof(\"{column}\")='integer' THEN \"{column}\" END FROM \"{descriptor.table}\""+suffix+' ORDER BY _rowid_ LIMIT ?')
    rows=_metadata_rows(connection, locator_query, parameters, _header_budget=_header_budget, upper=locator_upper, appearance=('row-locator',))
    if len(rows)>(MAX_ROWS if remaining is None else remaining) and key is None:
        raise HeaderBoundsError("header_reference_bound")
    if selected_whole:
        if len(rows) != locator_count or _state(connection, _header_budget=_header_budget) != locator_state:
            raise HeaderBoundsError("header_snapshot_changed")
        if _snapshot_schema_cookies(connection, budget, _header_budget=_header_budget) != locator_cookies:
            raise HeaderBoundsError("header_schema_cookie_changed")
    ids=[]
    for rowid,kind,_size,string,integer in rows:
        if descriptor.table=="work_board_events":
            if kind!="integer" or type(integer) is not int or integer!=rowid:raise HeaderBoundsError("header_rowid_unavailable")
            value=integer
        else:
            if kind!="text" or not string:raise HeaderBoundsError("header_scalar_unavailable")
            value=string
        ids.append(value)
    if len(ids)!=len(set(ids)):raise HeaderBoundsError("header_row_unavailable")
    for identity,row in zip(ids,rows):
        budget.resolve_future(descriptor,identity,row[0],database_identity=database_identity)
    budget.enroll((descriptor.table,r[0]) if database_identity is None
        else (database_identity,descriptor.table,r[0]) for r in rows)
    if _header_budget is None:
        budget.debit(_metadata_cost([list(r) for r in rows]), appearance=("locator-metadata", descriptor.table, key, tombstone, tuple(ids)))
    return tuple(ids)


async def discover_rows(db, descriptor, budget, *, _header_budget=None):
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    if type(budget) is not HeaderReadBudget or not any(descriptor is d for d in COMPOSITION_DESCRIPTORS.values()):
        raise HeaderBoundsError("header_descriptor_unavailable")
    return await (await db.connection()).run_sync(lambda c:_discover(c,descriptor,budget,_header_budget=_header_budget))


async def locate_exact_rows(db, descriptor, identity, budget, *, _header_budget=None):
    source_frame = _compiler_bounds._native_memory_header_logical_frame(db, budget)
    if source_frame is not None:
        if type(identity) is not str:
            raise HeaderBoundsError("header_request_bound")
        identity_bytes = _compiler_bounds._native_memory_utf8_width(identity)
        if not 0 < identity_bytes <= 512:
            raise HeaderBoundsError("header_request_bound")
        source_frame.debit(identity_bytes + 2 * (6 * identity_bytes + 2) + 2 * 41 + 4,
            appearance=("native-memory-header-logical", "locator-request"))
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    if type(identity) is not str or not 0<len(identity.encode())<=512:
        raise HeaderBoundsError("header_request_bound")
    if type(budget) is not HeaderReadBudget or not any(descriptor is d for d in COMPOSITION_DESCRIPTORS.values()):
        raise HeaderBoundsError("header_descriptor_unavailable")
    return await (await db.connection()).run_sync(lambda c:_discover(c,descriptor,budget,key=identity,_header_budget=_header_budget))


async def locate_operator_token(db, token_hash, budget, *, _header_budget=None):
    """Resolve the original unique bearer locator before any Root body."""
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    from src.memory.header_bounds import OPERATOR_SESSION
    from src.db.models import OperatorSession
    if (type(budget) is not HeaderReadBudget or type(token_hash) is not str
            or len(token_hash) != 64 or any(c not in "0123456789abcdef" for c in token_hash)):
        raise HeaderBoundsError("header_request_bound")
    def locate(connection):
        schema_cost = validate_descriptor_schema(connection, OPERATOR_SESSION, _header_budget=_header_budget)
        if _header_budget is None:
            budget.debit(schema_cost, appearance=("operator-token-schema",))
        name = _validate_locator(connection, "operator_sessions", "token_hash", OperatorSession, budget=budget, _header_budget=_header_budget)
        rows = _metadata_rows(connection, 'SELECT _rowid_,typeof(id),octet_length(id),'
            'CASE WHEN typeof(id)=\'text\' AND octet_length(id) BETWEEN 1 AND 512 THEN id END '
            f'FROM operator_sessions INDEXED BY "{name}" WHERE token_hash=? LIMIT 2', (token_hash,), _header_budget=_header_budget, upper=_metadata_upper(2, (20,44,20,3074)), appearance=('token-locator',))
        if _header_budget is None:
            budget.debit(_metadata_cost([list(r) for r in rows]), appearance=("operator-token-locator",))
        if len(rows) > 1 or any(type(r[0]) is not int or r[1] != "text" or not r[3] for r in rows):
            raise HeaderBoundsError("header_row_unavailable")
        budget.enroll(("operator_sessions", r[0]) for r in rows)
        return tuple(r[3] for r in rows)
    return await (await db.connection()).run_sync(locate)


