@dataclass(frozen=True,eq=False)
class CompositionHeaderCertificate:
    connection: object
    transaction: object
    driver: object
    changes: int
    rows: object
    budget: HeaderReadBudget
    seal: object
    issued_id: int=0
    raw_owner: object=None
    schema_cookies: object=None
    common_certificate: object=None
    original_selection: object=None
    absent: tuple=()
    metadata_budget: object=None


def _validate(connection,certificate):
    if type(certificate) is not CompositionHeaderCertificate or certificate.seal is not _SEAL or certificate.issued_id!=id(certificate) or certificate.connection is not connection:
        raise HeaderBoundsError("header_certificate_unavailable")
    if certificate.metadata_budget is not None and certificate.metadata_budget is not certificate.budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    if certificate.raw_owner is not None:
        certificate.raw_owner._validate_budget(certificate.budget)
    if _state(connection,raw_owner=certificate.raw_owner,_header_budget=certificate.metadata_budget)!=(certificate.transaction,certificate.driver,certificate.changes):
        raise HeaderBoundsError("header_certificate_stale")
    if certificate.schema_cookies is not None and _snapshot_schema_cookies(connection,certificate.budget,_header_budget=certificate.metadata_budget)!=certificate.schema_cookies:
        raise HeaderBoundsError("header_certificate_stale")
    if certificate.common_certificate is not None:
        _validate(connection, certificate.common_certificate)
        certificate.original_selection.owner._validate_programme_selection(certificate.original_selection)


def preflight_programme_identity_component(common33, *, original_selection):
    """Only an original rollback/native guard selects this named exception."""
    from src.db.models import OperatorIdentity
    from src.memory.header_bounds import _descriptor
    connection, owner, budget = common33.connection, common33.raw_owner, common33.budget
    _validate(connection, common33)
    if common33.common_certificate is not None:
        raise HeaderBoundsError("programme_identity_owner_unavailable")
    if owner is None:
        from src.workspace.accounting_witness import CompositionSessionGuard
        owner = original_selection.owner
        if type(owner) is not CompositionSessionGuard:
            raise HeaderBoundsError("programme_identity_owner_unavailable")
    owner._validate_programme_selection(original_selection)
    namespace = common33.raw_owner._namespace if common33.raw_owner is not None else None
    if common33.metadata_budget is not None:
        _prepay_descriptor_compiler(connection, OperatorIdentity,
            ("id", "created_at", "revoked_at"), ("VARCHAR", "DATETIME", "DATETIME"),
            common33.metadata_budget, table="operator_identities")
    descriptor = _descriptor(OperatorIdentity, "id", ("id", "created_at", "revoked_at"))
    schema_cost = validate_descriptor_schema(connection, descriptor, _header_budget=common33.metadata_budget)
    if common33.metadata_budget is None:
        budget.debit(schema_cost, appearance=("programme-identity-schema",))
    # Validate the exact source-owned single text PK BINARY ascending locator.
    indexes = _descriptor_metadata_rows(connection, 'SELECT seq,name,"unique",origin,partial FROM pragma_index_list(?) LIMIT 2', (descriptor.table,), _header_budget=common33.metadata_budget, upper=_metadata_upper(2, (20,770,20,14,20)), appearance=('identity-indexes',), bounded_query='SELECT seq,CASE WHEN octet_length(name)<=128 THEN name END,"unique",CASE WHEN octet_length(origin)<=2 THEN origin END,partial FROM pragma_index_list(?) LIMIT 2')
    if common33.metadata_budget is None:
        budget.debit(_metadata_cost([list(row) for row in indexes]), appearance=("programme-identity-indexes",))
    if ((common33.metadata_budget is None and (len(indexes) != 1 or tuple(indexes[0]) != (0, "sqlite_autoindex_operator_identities_1", 1, "pk", 0)))
            or (common33.metadata_budget is not None and not _identity_index_matches(indexes))):
        raise HeaderBoundsError("programme_identity_locator_changed")
    parts = _descriptor_metadata_rows(connection, 'SELECT seqno,cid,name,desc,coll,key FROM pragma_index_xinfo(?) LIMIT 3', (indexes[0][1],), _header_budget=common33.metadata_budget, upper=_metadata_upper(3, (20,20,770,20,770,20)), appearance=('identity-parts',), bounded_query='SELECT seqno,cid,CASE WHEN octet_length(name)<=128 THEN name END,desc,CASE WHEN octet_length(coll)<=128 THEN coll END,key FROM pragma_index_xinfo(?) LIMIT 3')
    if common33.metadata_budget is None:
        budget.debit(_metadata_cost([list(row) for row in parts]), appearance=("programme-identity-index-parts",))
    if ((common33.metadata_budget is None and [tuple(row) for row in parts] != [(0, 0, "id", 0, "BINARY", 1), (1, -1, None, 0, "BINARY", 0)])
            or (common33.metadata_budget is not None and not _identity_parts_match(parts))):
        raise HeaderBoundsError("programme_identity_locator_changed")
    objects = _descriptor_metadata_rows(connection, 'SELECT type,name FROM sqlite_schema WHERE tbl_name=? ORDER BY rowid LIMIT 3', (descriptor.table,), _header_budget=common33.metadata_budget, upper=_metadata_upper(3, (44,770)), appearance=('identity-objects',), bounded_query='SELECT CASE WHEN octet_length(type)<=7 THEN type END,CASE WHEN octet_length(name)<=128 THEN name END FROM sqlite_schema WHERE tbl_name=? ORDER BY rowid LIMIT 3')
    if common33.metadata_budget is None:
        budget.debit(_metadata_cost([list(row) for row in objects]), appearance=("programme-identity-objects",))
    if ((common33.metadata_budget is None and [tuple(row) for row in objects] != [("table", descriptor.table), ("index", indexes[0][1])])
            or (common33.metadata_budget is not None and not _identity_objects_match(objects, descriptor.table, indexes[0][1]))):
        raise HeaderBoundsError("programme_identity_schema_changed")
    present, absent = [], []
    for identity in original_selection.identity_ids:
        ids = _discover(connection, descriptor, budget, key=identity, database_identity=namespace,_header_budget=common33.metadata_budget)
        if not ids:
            if owner is original_selection.owner:
                raise HeaderBoundsError("programme_source_identity_missing")
            absent.append(identity)
        elif ids != (identity,):
            raise HeaderBoundsError("programme_identity_locator_changed")
        else:
            present.append(identity)
    rows = _headers(connection, descriptor, tuple(present), _header_budget=common33.metadata_budget)
    budget.debit(sum(cost for _, cost in rows.values()), appearance=("programme-identity-headers", tuple(present)))
    state = _state(connection, raw_owner=common33.raw_owner, _header_budget=common33.metadata_budget)
    certificate = CompositionHeaderCertificate(connection, *state, MappingProxyType(rows), budget, _SEAL,
        raw_owner=common33.raw_owner, schema_cookies=_snapshot_schema_cookies(connection, budget, _header_budget=common33.metadata_budget),
        metadata_budget=common33.metadata_budget, common_certificate=common33, original_selection=original_selection, absent=tuple(absent))
    object.__setattr__(certificate, "issued_id", id(certificate))
    _validate(connection, certificate)
    return certificate


def read_programme_identity(certificate, identity):
    """Exact original Identity3 body, fully debited before scalar strings."""
    if certificate.common_certificate is None:
        raise HeaderBoundsError("programme_identity_certificate_unavailable")
    _validate(certificate.connection, certificate)
    row = certificate.rows.get(("operator_identities", identity))
    if row is None:
        if identity in certificate.absent:
            return None
        raise HeaderBoundsError("header_row_unavailable")
    certificate.budget.debit(row[1], appearance=("programme-identity-body", identity))
    records = list(_sql(certificate.connection,
        'SELECT "id","created_at","revoked_at" FROM operator_identities WHERE id=? LIMIT 2', (identity,)))
    if len(records) != 1:
        raise HeaderBoundsError("header_row_unavailable")
    return tuple(records[0])



async def read_current_method_pointer(db, *, original_selection):
    """ADR-035 transient read selected by the genuine original admission guard.

    This does not register a generic body descriptor or authenticate a method:
    CurrentMethod still owns the pointer MAC and canonical version checks.
    """
    from src.workspace.accounting_witness import CompositionSessionGuard
    from src.db.task_method_models import TaskMethodActive
    from src.memory.header_bounds import _descriptor
    from src.workspace.accounting_continuity import _ProgrammeSelection
    if type(original_selection) is not _ProgrammeSelection:
        raise HeaderBoundsError("task_method_pointer_owner_unavailable")
    guard = original_selection.owner
    if (type(guard) is not CompositionSessionGuard or guard.db is not db
            or guard._prospective_admission is None
            or guard._prospective_admission[0] is not original_selection):
        raise HeaderBoundsError("task_method_pointer_owner_unavailable")
    guard._validate_programme_selection(original_selection)
    common33 = original_selection.common33
    budget = common33.budget
    binding = guard._prospective_admission_facts[2]
    scope = (binding.owner_identity_id, binding.goal_id, binding.goal_revision, "research")
    columns = ("id", "owner_identity_id", "goal_id", "goal_revision", "family", "revision",
        "binding_json", "previous_binding_json", "baseline", "signature_key_id", "signature_mac", "updated_at")
    sql_types = ("VARCHAR", "VARCHAR", "VARCHAR", "INTEGER", "VARCHAR", "INTEGER",
        "VARCHAR", "VARCHAR", "BOOLEAN", "VARCHAR", "VARCHAR", "DATETIME")

    def read(connection):
        guard._validate_programme_selection(original_selection)
        _validate(connection, common33)
        if connection is not common33.connection:
            raise HeaderBoundsError("task_method_pointer_owner_unavailable")
        # Compiler/descriptor construction is a separate prepaid appearance.
        _prepay_descriptor_compiler(connection, TaskMethodActive, columns, sql_types,
            budget, table="task_method_active")
        descriptor = _descriptor(TaskMethodActive, "id", columns)
        if descriptor.sql_types != sql_types or tuple(TaskMethodActive.__table__.columns.keys()) != columns:
            raise HeaderBoundsError("task_method_pointer_schema_changed")
        schema = _descriptor_xinfo_rows(connection, (21, 8, 12, "task_method_active", 13),
            budget=budget, upper=_metadata_upper(13, (23, 10, 2, 2, 1)))
        expected = [(name, kind, 1, int(name == "id"), 0) for name, kind in zip(columns, sql_types)]
        if [tuple(row) for row in schema] != expected:
            raise HeaderBoundsError("task_method_pointer_schema_changed")
        layout = _metadata_rows(connection,
            'SELECT wr FROM pragma_table_list WHERE schema="main" AND name=? LIMIT 2',
            ("task_method_active",), _header_budget=budget,
            upper=_metadata_upper(2, (20,)), appearance=("task-method-pointer-layout",))
        if [tuple(row) for row in layout] != [(0,)]:
            raise HeaderBoundsError("task_method_pointer_schema_changed")
        indexes = _metadata_rows(connection,
            'SELECT seq,CASE WHEN octet_length(name)<=128 THEN name END,"unique",'
            'CASE WHEN octet_length(origin)<=2 THEN origin END,partial '
            'FROM pragma_index_list(?) LIMIT 5', ("task_method_active",),
            _header_budget=budget, upper=_metadata_upper(5, (20, 770, 20, 14, 20)),
            appearance=("task-method-pointer-indexes",))
        definitions = {
            "sqlite_autoindex_task_method_active_1": (1, "pk", ("id",)),
            "sqlite_autoindex_task_method_active_2": (1, "u", columns[1:5]),
            "ix_task_method_active_owner_identity_id": (0, "c", ("owner_identity_id",)),
            "ix_task_method_active_goal_id": (0, "c", ("goal_id",)),
        }
        if (len(indexes) != 4 or {row[1] for row in indexes} != set(definitions)
                or {row[0] for row in indexes} != set(range(4))):
            raise HeaderBoundsError("task_method_pointer_locator_changed")
        for seq, name, unique, origin, partial in indexes:
            if (any(type(value) is not int for value in (seq, unique, partial))
                    or (unique, origin, partial) != (*definitions[name][:2], 0)):
                raise HeaderBoundsError("task_method_pointer_locator_changed")
            keys = definitions[name][2]
            parts = _metadata_rows(connection,
                'SELECT seqno,cid,CASE WHEN octet_length(name)<=128 THEN name END,desc,'
                'CASE WHEN octet_length(coll)<=128 THEN coll END,key '
                'FROM pragma_index_xinfo(?) LIMIT ?', (name, len(keys) + 2),
                _header_budget=budget, upper=_metadata_upper(len(keys) + 2, (20,20,770,20,770,20)),
                appearance=("task-method-pointer-index-parts", name))
            expected_parts = [(index, columns.index(key), key, 0, "BINARY", 1)
                for index, key in enumerate(keys)] + [(len(keys), -1, None, 0, "BINARY", 0)]
            if [tuple(row) for row in parts] != expected_parts:
                raise HeaderBoundsError("task_method_pointer_locator_changed")
        # Exact compound scope, no status filter or unbounded ID delivery.
        selected = _metadata_rows(connection,
            'SELECT CASE WHEN typeof(id)=\'text\' AND octet_length(id) BETWEEN 1 AND 512 '
            'THEN id END,_rowid_ FROM task_method_active '
            'WHERE owner_identity_id=? AND goal_id=? AND goal_revision=? AND family=? LIMIT 2',
            scope, _header_budget=budget, upper=_metadata_upper(2, (3074, 20)),
            appearance=("task-method-pointer-scope",))
        if len(selected) > 1:
            raise HeaderBoundsError("task_method_pointer_ambiguous")
        if not selected:
            foreign = _metadata_rows(connection,
                'SELECT _rowid_ FROM task_method_active '
                'WHERE goal_id=? AND goal_revision=? AND family=? LIMIT 1',
                scope[1:], _header_budget=budget, upper=_metadata_upper(1, (20,)),
                appearance=("task-method-pointer-foreign-existence",))
            for row in foreign:
                _descriptor_integer_size(row[0])
                budget.enroll({("task_method_active", row[0])})
            _validate(connection, common33)
            guard._validate_programme_selection(original_selection)
            return None, bool(foreign)
        identifier, rowid = selected[0]
        if type(identifier) is not str or not identifier:
            raise HeaderBoundsError("task_method_pointer_locator_changed")
        _descriptor_integer_size(rowid)
        budget.enroll({("task_method_active", rowid)})
        headers = _headers(connection, descriptor, (identifier,), _header_budget=budget)
        physical, upper = headers[("task_method_active", identifier)]
        if physical != rowid:
            raise HeaderBoundsError("task_method_pointer_locator_changed")
        budget.debit(upper, appearance=("task-method-pointer-complete-header", identifier))
        # Raw body, typed materialization and returned object copy each spend.
        for appearance in ("body", "materialization", "return-copy"):
            budget.debit(upper, appearance=("task-method-pointer", appearance, identifier))
        _validate(connection, common33)
        guard._validate_programme_selection(original_selection)
        rows = list(_sql(connection, 'SELECT ' + ','.join('"' + name + '"' for name in columns)
            + ' FROM task_method_active WHERE id=? LIMIT 2', (identifier,)))
        if len(rows) != 1:
            raise HeaderBoundsError("task_method_pointer_locator_changed")
        pointer = TaskMethodActive.model_validate(dict(zip(columns, rows[0])))
        if (pointer.owner_identity_id, pointer.goal_id, pointer.goal_revision, pointer.family) != scope:
            raise HeaderBoundsError("task_method_pointer_locator_changed")
        _validate(connection, common33)
        guard._validate_programme_selection(original_selection)
        return pointer, False

    return await (await db.connection()).run_sync(read)


def _selected_schema_census_sql():
    """Closed ORIGINAL schema policy; no caller SQL or schema-name input."""
    def quote(value):
        return "'" + value.replace("'", "''") + "'"
    def members(values):
        return ", ".join(quote(value) for value in sorted(values))
    tables = {*_SCHEMA_TABLES, "alembic_version"}
    auto_max = dict(_AUTO_MAX)
    auto_max.setdefault("alembic_version", 1)
    auto_cases = []
    for table, bound in sorted(auto_max.items()):
        prefix = "sqlite_autoindex_" + table + "_"
        suffix = f"substr(name, {len(prefix) + 1})"
        auto_cases.append(f"WHEN tbl_name = {quote(table)} THEN ("
            f"{suffix} <> '' AND instr(name, char(0)) = 0 AND "
            f"{suffix} NOT GLOB '*[^0-9]*' AND CAST({suffix} AS INTEGER) BETWEEN 1 AND {bound})")
    auto = "CASE " + " ".join(auto_cases) + " ELSE 0 END"
    prefix = "'sqlite_autoindex_' || tbl_name || '_'"
    task_names = {"ix_task_method_active_goal_id", "ix_task_method_active_owner_identity_id"}
    index = (f"CASE WHEN substr(name, 1, length({prefix})) = ({prefix}) COLLATE BINARY THEN ({auto}) "
        f"WHEN tbl_name = 'task_method_active' OR name IN ({members(task_names)}) "
        f"THEN (tbl_name = 'task_method_active' AND name IN ({members(task_names)})) "
        f"ELSE (tbl_name IN ({members(tables)}) AND name IN ({members(_NAMED_INDEXES)})) END")
    triggers = [f"(name = {quote(name)} AND tbl_name = {quote(spec[1])})"
        for name, spec in _FTS_SQL.items() if spec[0] == "trigger"]
    trigger = ("(tbl_name = 'operator_sessions' AND name IN "
        "('operator_principal_required_insert', 'operator_principal_required_update')) OR "
        + " OR ".join(triggers))
    valid = (f"CASE type WHEN 'table' THEN (name = tbl_name COLLATE BINARY AND "
        f"name IN ({members(tables | {'sqlite_sequence'} | set(_FTS_META))})) "
        f"WHEN 'index' THEN ({index}) WHEN 'trigger' THEN ({trigger}) ELSE 0 END")
    ordinal = "CASE name " + " ".join(f"WHEN {quote(name)} THEN {index}"
        for index, name in enumerate(_FTS_SQL, 1)) + " ELSE 0 END"
    return ("WITH capped AS (SELECT rowid, "
        "CASE WHEN octet_length(type) <= 7 THEN type END AS type, "
        "CASE WHEN octet_length(name) <= 128 THEN name END AS name, "
        "CASE WHEN octet_length(tbl_name) <= 128 THEN tbl_name END AS tbl_name "
        "FROM sqlite_schema ORDER BY rowid LIMIT 1360) "
        f"SELECT rowid, CASE WHEN ({valid}) THEN 1 ELSE 0 END AS original_object_valid, "
        f"{ordinal} AS original_fts_name_ordinal FROM capped ORDER BY rowid LIMIT 1360")


def _census_decimal_width(value):
    if type(value) is not int or not 0 <= value < 2**63:
        raise HeaderBoundsError("header_schema_object_unavailable")
    width = 1
    while value >= 10:
        value //= 10
        width += 1
    return width


def _census_source_leaves():
    # Source aliases only: no runtime roster tuple, item pairs or body copies.
    def keys(roster):
        for value in roster:
            if (type(value) is not str or not value or len(value) > 128
                    or any(not 32 <= ord(char) < 127 or char in "'\\\"" for char in value)):
                raise HeaderBoundsError("header_schema_source_unavailable")
    keys(_SCHEMA_TABLES)
    keys(_NAMED_INDEXES)
    # Exact streamed token membership requires delimiter-free source leaves.
    for name in _NAMED_INDEXES:
        if "|" in name:
            raise HeaderBoundsError("header_schema_source_unavailable")
    keys(_AUTO_MAX)
    keys(_FTS_SQL)
    keys(_FTS_META)
    for table in _AUTO_MAX:
        _census_decimal_width(_AUTO_MAX[table])
    for name in _FTS_SQL:
        spec = _FTS_SQL[name]
        if type(spec) is not tuple or len(spec) != 3 or type(spec[2]) is not str:
            raise HeaderBoundsError("header_schema_source_unavailable")
        kind = spec[0]
        table = spec[1]
        if (type(kind) is not str or kind not in ("table", "trigger")
                or type(table) is not str or not table or len(table) > 128
                or any(not 32 <= ord(char) < 127 or char in "'\\\"" for char in table)):
            raise HeaderBoundsError("header_schema_source_unavailable")
    if len(_FTS_SQL) != 15:
        raise HeaderBoundsError("header_schema_source_unavailable")


def _census_named_group_tables():
    # Source leaves only: no prefix roster, grouping dict or sorted lists.
    yield from _SCHEMA_TABLES
    if "task_method_active" not in _SCHEMA_TABLES:
        yield "task_method_active"


def _census_named_group_table(name):
    # The longest source table prefix partitions names independently of tbl_name.
    if not name.startswith(("ix_", "ux_")):
        return None
    selected = None
    width = 0
    for table in _census_named_group_tables():
        size = len(table)
        if (size > width and name.startswith(table, 3)
                and len(name) > size + 3 and name[size + 3] == "_"):
            selected = table
            width = size
    return selected


def _selected_schema_census_parts(*, numeric, factored_named=False, factored_auto=False):
    # Numeric mode emits widths only, and never sorts, formats or builds SQL.
    def part(value):
        return len(value) if numeric else value
    def number(value):
        return _census_decimal_width(value) if numeric else str(value)
    def quote(value):
        yield part("'")
        yield part(value)
        yield part("'")
    def members(values, *, source_order=False):
        first = True
        for value in values if numeric or source_order else sorted(values):
            if not first:
                yield part(", ")
            first = False
            yield from quote(value)
    def tables(extra=False):
        # Both passes traverse original leaves; neither builds a set/sorted list.
        yield from _SCHEMA_TABLES
        if "alembic_version" not in _SCHEMA_TABLES:
            yield "alembic_version"
        if extra:
            if "sqlite_sequence" not in _SCHEMA_TABLES:
                yield "sqlite_sequence"
            for name in _FTS_META:
                if name not in _SCHEMA_TABLES and name not in ("alembic_version", "sqlite_sequence"):
                    yield name
    def auto_keys():
        if numeric:
            yield from _AUTO_MAX
            if "alembic_version" not in _AUTO_MAX:
                yield "alembic_version"
        else:
            values = dict(_AUTO_MAX)
            values.setdefault("alembic_version", 1)
            yield from sorted(values)
    def suffix():
        yield part("substr(name, length('sqlite_autoindex_' || tbl_name || '_') + 1)")
    def auto():
        yield from suffix()
        yield part(" <> '' AND instr(name, char(0)) = 0 AND ")
        yield from suffix()
        yield part(" NOT GLOB '*[^0-9]*' AND CAST(")
        yield from suffix()
        if factored_auto:
            yield part(" AS INTEGER) BETWEEN 1 AND (")
            yield part(_AUTO_LOOKUP)
            yield part(")")
        else:
            yield part(" AS INTEGER) BETWEEN 1 AND (CASE tbl_name ")
            first = True
            for table in auto_keys():
                if not first:
                    yield part(" ")
                first = False
                yield part("WHEN ")
                yield from quote(table)
                yield part(" THEN ")
                yield number(_AUTO_MAX.get(table, 1))
            yield part(" ELSE 0 END)")
    def named_indexes():
        first_group = True
        if factored_named:
            yield part(_FACTORED_MEMBERSHIP)
            first_group = False
        else:
            for kind in ("ix_", "ux_"):
                for table in _census_named_group_tables():
                    first = True
                    for value in _NAMED_INDEXES:
                        if (not value.startswith(kind) or not value.startswith(table, 3)
                                or len(value) <= len(table) + 3 or value[len(table) + 3] != "_"
                                or _census_named_group_table(value) != table):
                            continue
                        offset = len(table) + 4
                        if first:
                            if not first_group:
                                yield part(" OR ")
                            first_group = False
                            yield part("(substr(name, 1, ")
                            yield number(offset)
                            yield part(") = '")
                            yield part(kind)
                            yield part(table)
                            yield part("_' COLLATE BINARY AND instr('")
                        first = False
                        yield part("|")
                        # Sizing never slices a source name; the paid pass does once.
                        yield len(value) - offset if numeric else value[offset:]
                    if not first:
                        yield part("|', '|' || substr(name, ")
                        yield number(offset + 1)
                        yield part(") || '|') > 0)")
        first = True
        for value in _NAMED_INDEXES:
            if _census_named_group_table(value) is not None:
                continue
            if first:
                if not first_group:
                    yield part(" OR ")
                yield part("(name IN (")
            else:
                yield part(", ")
            first = False
            yield from quote(value)
        if not first:
            yield part("))")
        if first_group and first:
            yield part("0")
    def index():
        yield part("CASE WHEN substr(name, 1, length('sqlite_autoindex_' || tbl_name || '_')) = ('sqlite_autoindex_' || tbl_name || '_') COLLATE BINARY THEN (")
        yield from auto()
        yield part(") WHEN tbl_name = 'task_method_active' OR name IN (")
        task = ("ix_task_method_active_goal_id", "ix_task_method_active_owner_identity_id")
        yield from members(task)
        yield part(") THEN (tbl_name = 'task_method_active' AND name IN (")
        yield from members(task)
        yield part(")) ELSE (tbl_name IN (")
        yield from members(tables(), source_order=True)
        # SUBSTR stops at embedded NUL; original full-name IN never accepts it.
        yield part(") AND instr(name, char(0)) = 0 AND instr(name, '|') = 0 AND (")
        yield from named_indexes()
        yield part(")) END")
    def trigger():
        yield part("(tbl_name = 'operator_sessions' AND name IN ('operator_principal_required_insert', 'operator_principal_required_update')) OR ")
        first = True
        for name in _FTS_SQL:
            spec = _FTS_SQL[name]
            if spec[0] != "trigger":
                continue
            if not first:
                yield part(" OR ")
            first = False
            yield part("(name = ")
            yield from quote(name)
            yield part(" AND tbl_name = ")
            yield from quote(spec[1])
            yield part(")")
    yield part("WITH capped AS (SELECT rowid, CASE WHEN octet_length(type) <= 7 THEN type END AS type, CASE WHEN octet_length(name) <= 128 THEN name END AS name, CASE WHEN octet_length(tbl_name) <= 128 THEN tbl_name END AS tbl_name FROM sqlite_schema ORDER BY rowid LIMIT 1360) SELECT rowid, CASE WHEN (CASE type WHEN 'table' THEN (name = tbl_name COLLATE BINARY AND name IN (")
    yield from members(tables(True), source_order=True)
    yield part(")) WHEN 'index' THEN (")
    yield from index()
    yield part(") WHEN 'trigger' THEN (")
    yield from trigger()
    yield part(") ELSE 0 END) THEN 1 ELSE 0 END AS original_object_valid, CASE name ")
    ordinal = 0
    for name in _FTS_SQL:
        ordinal += 1
        if ordinal != 1:
            yield part(" ")
        yield part("WHEN ")
        yield from quote(name)
        yield part(" THEN ")
        yield number(ordinal)
    yield part(" ELSE 0 END AS original_fts_name_ordinal FROM capped ORDER BY rowid LIMIT 1360")


def _selected_schema_census_input_upper(*, aggregate=False):
    _census_source_leaves()
    length = count = 0
    parts = (_selected_schema_factored_auto_aggregate_parts(numeric=True) if aggregate
        else _selected_schema_census_parts(numeric=True))
    for width in parts:
        length += width
        count += 1
    # One join frontier, final SQL and original driver's input copy.
    upper = 2 + length + 2 * count + max(0, count - 1) + 2 * (length + 2) + 6
    # Container slots/aliases are charged too, including original FTS DDL refs.
    # Two table branches now stream: remove ONLY their two set and two sorted
    # list appearances (4*2230). Retain the other four source/union alias reserves.
    upper += 4 * (2 + sum(len(value) + 3 for value in _SCHEMA_TABLES))
    # Groups stream original leaves: no named sort/list/dict/prefix allocation.
    # Every matched name is sliced once in the paid fragment stream.
    for name in _NAMED_INDEXES:
        table = _census_named_group_table(name)
        if table is not None:
            upper += len(name) - len(table) - 4 + 2
    # Two formatted decimal offsets per occupied group, each one actual string.
    for kind in ("ix_", "ux_"):
        for table in _census_named_group_tables():
            for name in _NAMED_INDEXES:
                if (name.startswith(kind) and name.startswith(table, 3)
                        and len(name) > len(table) + 3 and name[len(table) + 3] == "_"
                        and _census_named_group_table(name) == table):
                    upper += _census_decimal_width(len(table) + 4) + 2
                    upper += _census_decimal_width(len(table) + 5) + 2
                    break
    # Other source rosters retain their existing conservative slot appearances.
    upper += 6 * (2 + sum(len(value) + 3 for value in _AUTO_MAX))
    upper += 6 * (2 + sum(len(value) + 3 for value in _FTS_META))
    upper += 3 * (2 + sum(3 + len(name) + 2 + _metadata_size(_FTS_SQL[name]) + 1 for name in _FTS_SQL))
    upper += 3 * (2 + sum(len(table) + 3 + 20 for table in _AUTO_MAX))
    # Each CASE bound is formatted once; dynamic auto suffix has no offset string.
    for table in _AUTO_MAX:
        upper += _census_decimal_width(_AUTO_MAX[table]) + 2
    if "alembic_version" not in _AUTO_MAX:
        upper += 3
    for ordinal in range(1, len(_FTS_SQL) + 1):
        upper += _census_decimal_width(ordinal) + 2
    # Literal task/default/union slots, not retained new source authority.
    upper += 6 * (2 + len("alembic_version") + 3 + len("sqlite_sequence") + 3)
    upper += 3 * (2 + len("ix_task_method_active_goal_id") + 3
        + len("ix_task_method_active_owner_identity_id") + 3)
    return upper


def _selected_schema_census_flat_sql():
    return "".join(_selected_schema_census_parts(numeric=False))


